return Mono.defer(() -> {
    TelemetrySample stamped = new TelemetrySample(
            sample.deviceId(), sample.metric(), sample.value(), sample.tDevice(), clock.instant());
    Object event = policy.isWithinBounds(stamped)
            ? new TelemetrySampleValidated(stamped)
            : new ValidationFailed(stamped);
    return port.publish(event);
});

